import json
import logging
from pathlib import Path
from fastapi import APIRouter, HTTPException
from typing import Dict, Any, List

router = APIRouter()
logger = logging.getLogger(__name__)

# Path to the ML results generated by the pipeline
ML_RESULTS_PATH = Path(__file__).resolve().parent.parent.parent / "data" / "ml_results.json"

def _load_ml_results() -> Dict[str, Any]:
    if not ML_RESULTS_PATH.is_file():
        logger.error(f"ML results file not found at {ML_RESULTS_PATH}")
        raise FileNotFoundError("ML results not generated yet")
    with open(ML_RESULTS_PATH, "r", encoding="utf-8") as f:
        return json.load(f)

@router.get("/anomaly/{sale_id}/explain", response_model=List[Dict[str, Any]])
def explain_anomaly(sale_id: str):
    """Return feature‑importance explanation for a specific anomalous sale.

    The endpoint reads the cached ``ml_results.json`` produced by the
    ``ml/train.py`` pipeline, locates the anomaly with the matching ``sale_id``
    and returns the list of feature attribution dictionaries produced by the
    ``compute_feature_importance`` function.
    """
    try:
        ml_data = _load_ml_results()
    except Exception as e:
        logger.error(f"Failed to load ML results: {e}")
        raise HTTPException(status_code=500, detail="ML results unavailable")

    # Verify the anomaly exists
    anomalies = ml_data.get("anomalies", [])
    anomaly = next((a for a in anomalies if str(a.get("sale_id")) == sale_id), None)
    if not anomaly:
        raise HTTPException(status_code=404, detail="Anomaly not found for given sale_id")

    # Return the pre‑computed explainability payload (same for all anomalies in this demo)
    explainability = ml_data.get("explainability", [])
    if not explainability:
        # Fallback – compute on‑the‑fly from raw data if needed (not implemented)
        logger.warning("Explainability data missing in ML results; returning empty list")
        return []
    return explainability
